__defs["src/lin/history.js"] = function (__exports, __req) {
// History representation.
//
// A history is an ordered list of operations. Order is carried by two integer
// event positions -- `call` and `ret` -- which are indices into the original
// event stream, NOT timestamps. That matters: a linearizability checker only
// ever needs the partial order "a returned before b was called", and inventing
// timestamps where the source had none would be fabricating precision.

/**
 * @typedef {object} Operation
 * @property {number} id           stable id, unique within the history
 * @property {number} clientId     which client issued it (a client is sequential)
 * @property {string} key          partition key; P-compositionality splits on this
 * @property {*} input
 * @property {*} output
 * @property {number} call         event-stream position of the invocation
 * @property {number} ret          event-stream position of the response
 * @property {number} [callTick]   simulated tick of the call, present when the
 *   history came from the simulator rather than from a log. The checker never
 *   reads it -- only the event-stream order matters -- but the diagrams do.
 * @property {number} [retTick]    simulated tick of the response
 * @property {boolean} [abandoned] the client gave up waiting and retired
 * @property {number} [attempts]   how many times the client re-sent it
 */

/**
 * Validate a history and fail loudly on anything malformed. A checker that
 * silently accepts a broken history will happily print a verdict about nothing.
 *
 * @param {Operation[]} ops
 * @returns {Operation[]} the same array, validated
 */
function validateHistory(ops) {
  if (!Array.isArray(ops)) {
    throw new TypeError('history must be an array of operations, got ' + typeof ops);
  }
  const seenId = new Set();
  const positions = new Set();
  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    if (op === null || typeof op !== 'object') {
      throw new TypeError('history[' + i + '] is not an object');
    }
    for (const field of ['id', 'clientId', 'call', 'ret']) {
      if (!Number.isInteger(op[field])) {
        throw new TypeError('history[' + i + '].' + field + ' must be an integer, got ' + String(op[field]));
      }
    }
    if (typeof op.key !== 'string') {
      throw new TypeError('history[' + i + '].key must be a string, got ' + typeof op.key);
    }
    if (op.input === null || typeof op.input !== 'object') {
      throw new TypeError('history[' + i + '].input must be an object');
    }
    if (op.output === null || typeof op.output !== 'object') {
      throw new TypeError('history[' + i + '].output must be an object');
    }
    if (op.ret <= op.call) {
      throw new RangeError(
        'history[' + i + ']: response position ' + op.ret + ' must come after call position ' + op.call
      );
    }
    if (seenId.has(op.id)) throw new Error('history: duplicate operation id ' + op.id);
    seenId.add(op.id);
    if (positions.has(op.call)) throw new Error('history: duplicate event position ' + op.call);
    positions.add(op.call);
    if (positions.has(op.ret)) throw new Error('history: duplicate event position ' + op.ret);
    positions.add(op.ret);
  }
  return ops;
}

/**
 * Split a history into independent sub-histories, one per key.
 *
 * This is P-compositionality (Herlihy & Wing's locality theorem): a history over
 * independent objects is linearizable if and only if every per-object
 * sub-history is. It is not an optimisation detail -- it is the difference
 * between an exponential search over 90 operations and three searches over 30.
 *
 * @param {Operation[]} ops
 * @returns {Map<string, Operation[]>}
 */
function partitionByKey(ops) {
  /** @type {Map<string, Operation[]>} */
  const parts = new Map();
  for (const op of ops) {
    let bucket = parts.get(op.key);
    if (!bucket) {
      bucket = [];
      parts.set(op.key, bucket);
    }
    bucket.push(op);
  }
  return parts;
}

/**
 * Number of concurrent operations at each event position -- used by the demo's
 * space-time diagram to lay out lanes, and useful as a rough difficulty signal.
 * @param {Operation[]} ops
 * @returns {number}
 */
function maxConcurrency(ops) {
  /** @type {Array<{pos:number, delta:number}>} */
  const points = [];
  for (const op of ops) {
    points.push({ pos: op.call, delta: 1 });
    points.push({ pos: op.ret, delta: -1 });
  }
  points.sort((a, b) => a.pos - b.pos);
  let cur = 0;
  let max = 0;
  for (const p of points) {
    cur += p.delta;
    if (cur > max) max = cur;
  }
  return max;
}

__exports.validateHistory = validateHistory;
__exports.partitionByKey = partitionByKey;
__exports.maxConcurrency = maxConcurrency;
};
__defs["src/lin/wgl.js"] = function (__exports, __req) {
// Linearizability checker: Wing & Gong's algorithm with Lowe's memoisation,
// plus P-compositionality.
//
// Deciding linearizability of a history against an arbitrary sequential
// specification is NP-complete (Gibbons & Korach 1997). That is not a caveat
// bolted onto this file, it is the reason the file has three return values
// instead of two. Every other checker in this portfolio returns
// unknown because its author chose to be honest about coverage. This one
// returns unknown because the alternative is a search that does not terminate
// in the time a human will wait.
//
// The search:
//   entries are the calls and responses in event order, as a doubly linked list
//   repeatedly try to linearize the earliest remaining call
//     if the model accepts it and the resulting (state, linearized-set) pair is
//     new, commit it: lift the call AND its response out of the list, and
//     restart from the front
//     otherwise move on to the next entry
//   reaching a response whose call is still in the list means the prefix is
//   dead -- undo the last commitment and continue from there
//   the list emptying means a full linearization was found
//
// The memo table is what makes this tractable. Two search paths that have
// linearized the same SET of operations and arrived at the same model state are
// interchangeable from that point on, so the second one is pruned. Correctness
// of that pruning rests entirely on model.stateKey being exact; see models.js.

const { validateHistory, partitionByKey } = __req("src/lin/history.js");

const DEFAULT_BUDGET = 4000000;

/**
 * @typedef {object} CheckResult
 * @property {string} verdict 'linearizable' | 'not-linearizable' | 'unknown'
 * @property {number} steps model transitions attempted
 * @property {number} budget
 * @property {number} operations
 * @property {number} partitions
 * @property {?Witness} witness
 * @property {PartitionResult[]} perPartition
 */

/**
 * @typedef {object} Witness
 * @property {string} key
 * @property {import('./history.js').Operation} blocked the response that could not be explained
 * @property {import('./history.js').Operation[]} prefix longest consistent explanation found
 * @property {string} text
 */

/**
 * @typedef {object} PartitionResult
 * @property {string} key
 * @property {string} verdict
 * @property {number} steps
 * @property {number} operations
 * @property {?Witness} witness
 */

/** Fixed-size bitset over `n` operations, keyed as a hex string for the memo. */
class Bitset {
  /** @param {number} n */
  constructor(n) {
    this.words = new Uint32Array(Math.ceil(n / 32) || 1);
  }
  /** @param {number} i */
  set(i) {
    this.words[i >>> 5] |= 1 << (i & 31);
  }
  /** @param {number} i */
  clear(i) {
    this.words[i >>> 5] &= ~(1 << (i & 31));
  }
  /** @returns {string} */
  key() {
    let s = '';
    for (let i = 0; i < this.words.length; i++) {
      s += this.words[i].toString(36) + '.';
    }
    return s;
  }
}

/**
 * Linked-list node for one event.
 * @typedef {object} Entry
 * @property {boolean} isCall
 * @property {number} idx        index of the operation within this partition
 * @property {import('./history.js').Operation} op
 * @property {?Entry} match      for a call, its response node
 * @property {?Entry} prev
 * @property {?Entry} next
 */

/**
 * @param {import('./history.js').Operation[]} ops
 * @returns {Entry} sentinel head
 */
function buildEntries(ops) {
  /** @type {Entry[]} */
  const events = [];
  for (let idx = 0; idx < ops.length; idx++) {
    const op = ops[idx];
    /** @type {Entry} */
    const call = { isCall: true, idx, op, match: null, prev: null, next: null };
    /** @type {Entry} */
    const ret = { isCall: false, idx, op, match: call, prev: null, next: null };
    call.match = ret;
    events.push(call, ret);
  }
  events.sort((a, b) => {
    const pa = a.isCall ? a.op.call : a.op.ret;
    const pb = b.isCall ? b.op.call : b.op.ret;
    return pa - pb;
  });
  /** @type {Entry} */
  const head = { isCall: false, idx: -1, op: /** @type {any} */ (null), match: null, prev: null, next: null };
  let cur = head;
  for (const e of events) {
    cur.next = e;
    e.prev = cur;
    cur = e;
  }
  cur.next = null;
  return head;
}

/** @param {Entry} node */
function unlink(node) {
  const prev = /** @type {Entry} */ (node.prev);
  prev.next = node.next;
  if (node.next) node.next.prev = prev;
}

/** @param {Entry} node */
function relink(node) {
  const prev = /** @type {Entry} */ (node.prev);
  prev.next = node;
  if (node.next) node.next.prev = node;
}

/**
 * Check one partition.
 *
 * @param {any} model
 * @param {import('./history.js').Operation[]} ops
 * @param {number} budget
 * @param {{acceptOnBlock?: boolean}} [sabotage] build-flag fixtures, see src/bugs.js
 * @returns {{verdict:string, steps:number, witness:?Witness}}
 */
function checkPartition(model, ops, budget, sabotage) {
  const n = ops.length;
  if (n === 0) return { verdict: 'linearizable', steps: 0, witness: null };

  const head = buildEntries(ops);
  const linearized = new Bitset(n);
  /** @type {Map<string, Set<string>>} */
  const memo = new Map();
  /** @type {Array<{entry: Entry, state: any}>} */
  const calls = [];

  let state = model.init();
  let entry = head.next;
  let steps = 0;

  // Deepest partial linearization seen, kept for the witness. The blocking
  // response at that depth is the most informative thing the search learns
  // about WHY the history has no linearization.
  let deepest = -1;
  /** @type {?Entry} */
  let deepestBlock = null;
  /** @type {import('./history.js').Operation[]} */
  let deepestPrefix = [];

  while (head.next !== null) {
    if (steps >= budget) {
      return { verdict: 'unknown', steps, witness: null };
    }
    const e = /** @type {Entry} */ (entry);
    if (e.isCall) {
      steps++;
      const [ok, nextState] = model.step(state, e.op.input, e.op.output);
      let committed = false;
      if (ok) {
        linearized.set(e.idx);
        const bits = linearized.key();
        const sk = model.stateKey(nextState);
        let states = memo.get(bits);
        if (!states) {
          states = new Set();
          memo.set(bits, states);
        }
        if (!states.has(sk)) {
          states.add(sk);
          calls.push({ entry: e, state });
          state = nextState;
          unlink(e);
          unlink(/** @type {Entry} */ (e.match));
          entry = head.next;
          committed = true;
        } else {
          linearized.clear(e.idx);
        }
      }
      if (!committed) {
        entry = e.next;
      }
    } else {
      if (calls.length > deepest) {
        deepest = calls.length;
        deepestBlock = e;
        deepestPrefix = calls.map((c) => c.entry.op);
      }
      if (calls.length === 0) {
        if (sabotage && sabotage.acceptOnBlock) {
          // PLANTED FIXTURE (build flag `checker-accept-on-block`). The search
          // has proven no linearization exists, and this branch reports success
          // anyway. It exists so the suite can watch the checker's rejection
          // path fail; see test/sabotage.test.js.
          return { verdict: 'linearizable', steps, witness: null };
        }
        return {
          verdict: 'not-linearizable',
          steps,
          witness: buildWitness(model, ops, /** @type {Entry} */ (deepestBlock), deepestPrefix),
        };
      }
      const top = /** @type {{entry: Entry, state: any}} */ (calls.pop());
      state = top.state;
      linearized.clear(top.entry.idx);
      relink(/** @type {Entry} */ (top.entry.match));
      relink(top.entry);
      entry = top.entry.next;
    }
  }
  return { verdict: 'linearizable', steps, witness: null };
}

/**
 * @param {any} model
 * @param {import('./history.js').Operation[]} ops
 * @param {Entry} block
 * @param {import('./history.js').Operation[]} prefix
 * @returns {Witness}
 */
function buildWitness(model, ops, block, prefix) {
  const blockedOp = block.op;
  const last = prefix.length > 0 ? prefix[prefix.length - 1] : null;
  let text = model.describe(blockedOp) + ' cannot be placed anywhere in the order';
  if (last) {
    text += '; the longest consistent explanation ends at ' + model.describe(last);
  }
  return { key: blockedOp.key, blocked: blockedOp, prefix, text };
}

/**
 * Check a whole history.
 *
 * @param {any} model
 * @param {import('./history.js').Operation[]} ops
 * @param {{budget?: number, sabotage?: {acceptOnBlock?: boolean}}} [opts]
 * @returns {CheckResult}
 */
function check(model, ops, opts) {
  validateHistory(ops);
  const budget = opts && opts.budget !== undefined ? opts.budget : DEFAULT_BUDGET;
  if (!Number.isInteger(budget) || budget <= 0) {
    throw new RangeError('budget must be a positive integer, got ' + String(budget));
  }
  const sabotage = (opts && opts.sabotage) || undefined;

  const parts = partitionByKey(ops);
  // Deterministic order: the verdict and the witness must not depend on Map
  // iteration order, so keys are sorted before the search.
  const keys = Array.from(parts.keys()).sort();

  /** @type {PartitionResult[]} */
  const perPartition = [];
  let totalSteps = 0;
  let sawUnknown = false;
  /** @type {?Witness} */
  let firstWitness = null;

  // Budget is shared across partitions, so a 5-key history cannot quietly spend
  // 5x the advertised budget.
  let remaining = budget;

  for (const key of keys) {
    const bucket = /** @type {import('./history.js').Operation[]} */ (parts.get(key));
    const share = Math.max(1, remaining);
    const res = checkPartition(model, bucket, share, sabotage);
    remaining -= res.steps;
    totalSteps += res.steps;
    perPartition.push({
      key,
      verdict: res.verdict,
      steps: res.steps,
      operations: bucket.length,
      witness: res.witness,
    });
    if (res.verdict === 'not-linearizable') {
      if (!firstWitness) firstWitness = res.witness;
      // A single non-linearizable sub-history makes the whole history
      // non-linearizable; stop, the answer cannot change.
      return {
        verdict: 'not-linearizable',
        steps: totalSteps,
        budget,
        operations: ops.length,
        partitions: keys.length,
        witness: firstWitness,
        perPartition,
      };
    }
    if (res.verdict === 'unknown') sawUnknown = true;
    if (remaining <= 0 && keys.indexOf(key) < keys.length - 1) {
      sawUnknown = true;
      break;
    }
  }

  return {
    verdict: sawUnknown ? 'unknown' : 'linearizable',
    steps: totalSteps,
    budget,
    operations: ops.length,
    partitions: keys.length,
    witness: null,
    perPartition,
  };
}

__exports.DEFAULT_BUDGET = DEFAULT_BUDGET;
__exports.checkPartition = checkPartition;
__exports.check = check;
};
__defs["src/lin/models.js"] = function (__exports, __req) {
// Sequential specifications the checker linearizes against.
//
// A model is a plain object:
//   name        human label
//   init()      -> initial state (must be immutable or copied by step)
//   step(state, input, output) -> [ok, nextState]
//   stateKey(state) -> string, used as the memo key; two states with the same
//               key MUST be interchangeable for all future steps, or the cache
//               will prune a real linearization and produce a false
//               "not-linearizable". This is the single most dangerous line in
//               the checker, which is why every model states it explicitly.
//   describe(op) -> string, for witnesses and the space-time diagram

/**
 * The etcd single-register model, transcribed from porcupine_test.go so that
 * kedge's verdicts are comparable to Porcupine's published ones.
 *
 * Semantics that look odd but are deliberate, because Porcupine defines them
 * this way and parity is the whole point of the corpus run:
 *   * a write ALWAYS succeeds and always installs its value, even when the
 *     client never saw a response (`unknown`). A write that timed out may still
 *     have taken effect, and the model is permissive about it.
 *   * an operation with `unknown: true` is accepted by every branch, because
 *     the client learned nothing.
 */
const etcdRegisterModel = {
  name: 'etcd-register',
  init() {
    return null; // null is etcd's "key does not exist"
  },
  /**
   * @param {number|null} state
   * @param {{op:string, arg1?:number, arg2?:number}} input
   * @param {{exists?:boolean, value?:number, ok?:boolean, unknown?:boolean}} output
   * @returns {[boolean, number|null]}
   */
  step(state, input, output) {
    if (input.op === 'read') {
      const ok =
        output.unknown === true ||
        (output.exists === false && state === null) ||
        (output.exists === true && state === output.value);
      return [ok, state];
    }
    if (input.op === 'write') {
      return [true, /** @type {number} */ (input.arg1)];
    }
    if (input.op === 'cas') {
      const from = /** @type {number} */ (input.arg1);
      const to = /** @type {number} */ (input.arg2);
      const succeeded = output.ok === true;
      const ok =
        output.unknown === true ||
        (from === state && succeeded) ||
        (from !== state && !succeeded);
      const next = from === state ? to : state;
      return [ok, next];
    }
    throw new Error('etcd-register: unknown operation "' + String(input.op) + '"');
  },
  /** @param {number|null} state */
  stateKey(state) {
    return state === null ? 'nil' : String(state);
  },
  /** @param {{input:any, output:any}} op */
  describe(op) {
    const i = op.input;
    const o = op.output;
    if (i.op === 'read') {
      if (o.unknown) return 'read() -> unknown';
      return 'read() -> ' + (o.exists ? String(o.value) : 'null');
    }
    if (i.op === 'write') {
      return 'write(' + i.arg1 + ')' + (o.unknown ? ' -> unknown' : '');
    }
    return 'cas(' + i.arg1 + ', ' + i.arg2 + ') -> ' + (o.unknown ? 'unknown' : o.ok ? 'ok' : 'fail');
  },
};

/**
 * kedge's own key/value model, used for the simulator. Multi-key, which is what
 * makes P-compositionality do real work rather than being a no-op: the checker
 * splits the history by key and checks each sub-history independently.
 *
 * State is a single value (per key -- the partitioning happens outside the
 * model), so stateKey is exact, not an approximation.
 */
const kvRegisterModel = {
  name: 'kv-register',
  init() {
    return null;
  },
  /**
   * @param {string|null} state
   * @param {{op:string, value?:string}} input
   * @param {{value?:string|null, unknown?:boolean}} output
   * @returns {[boolean, string|null]}
   */
  step(state, input, output) {
    if (input.op === 'get') {
      if (output.unknown === true) return [true, state];
      const seen = output.value === undefined ? null : output.value;
      return [seen === state, state];
    }
    if (input.op === 'put') {
      // A put whose response was lost may or may not have landed; like the etcd
      // model we take the permissive branch and install the value.
      return [true, /** @type {string} */ (input.value)];
    }
    throw new Error('kv-register: unknown operation "' + String(input.op) + '"');
  },
  /** @param {string|null} state */
  stateKey(state) {
    return state === null ? 'nil' : 'v:' + state;
  },
  /** @param {{key:string, input:any, output:any}} op */
  describe(op) {
    const i = op.input;
    const o = op.output;
    if (i.op === 'get') {
      if (o.unknown) return 'get(' + op.key + ') -> unknown';
      return 'get(' + op.key + ') -> ' + (o.value === null || o.value === undefined ? 'null' : JSON.stringify(o.value));
    }
    return 'put(' + op.key + ', ' + JSON.stringify(i.value) + ')' + (o.unknown ? ' -> unknown' : '');
  },
};

/** @type {Record<string, typeof etcdRegisterModel>} */
const MODELS = {
  'etcd-register': etcdRegisterModel,
  'kv-register': /** @type {any} */ (kvRegisterModel),
};

__exports.etcdRegisterModel = etcdRegisterModel;
__exports.kvRegisterModel = kvRegisterModel;
__exports.MODELS = MODELS;
};
__defs["src/io/jepsen.js"] = function (__exports, __req) {
// Parser for Jepsen etcd history logs, as shipped in Porcupine's test_data.
//
// This deliberately reproduces Porcupine's own parsing semantics line for line
// (porcupine_test.go, parseJepsenLog), because the corpus is only useful as a
// ground truth if kedge is answering the same question about the same history.
// The three semantics worth naming:
//
//   1. `:info <op> :timed-out` lines are IGNORED. The operation stays pending,
//      and a response with `unknown: true` is appended at the very end of the
//      history. That models "the client never learned the outcome, and the
//      operation may have taken effect at any point afterwards".
//   2. `:fail :read :timed-out` produces a response with `unknown: true` AT
//      THAT POSITION, not at the end.
//   3. Anything else that does not match is skipped.
//
// Porcupine appends the trailing pending responses in Go map order, which is
// randomised. kedge sorts them by process id instead. That is safe rather than
// merely convenient: every trailing response sits after every call, so no
// ordering among them constrains any linearization.

const MAX_BYTES = 32 * 1024 * 1024;

const RE = {
  invokeRead: /^INFO\s+jepsen\.util\s+-\s+(\d+)\s+:invoke\s+:read\s+nil$/,
  invokeWrite: /^INFO\s+jepsen\.util\s+-\s+(\d+)\s+:invoke\s+:write\s+(\d+)$/,
  invokeCas: /^INFO\s+jepsen\.util\s+-\s+(\d+)\s+:invoke\s+:cas\s+\[(\d+)\s+(\d+)\]$/,
  returnRead: /^INFO\s+jepsen\.util\s+-\s+(\d+)\s+:ok\s+:read\s+(nil|\d+)$/,
  returnWrite: /^INFO\s+jepsen\.util\s+-\s+(\d+)\s+:ok\s+:write\s+(\d+)$/,
  returnCas: /^INFO\s+jepsen\.util\s+-\s+(\d+)\s+:(ok|fail)\s+:cas\s+\[(\d+)\s+(\d+)\]$/,
  timeoutRead: /^INFO\s+jepsen\.util\s+-\s+(\d+)\s+:fail\s+:read\s+:timed-out$/,
};

/**
 * @param {string} text raw log contents
 * @param {{source?: string}} [opts]
 * @returns {import('../lin/history.js').Operation[]}
 * @throws {Error} on input that is not a Jepsen log
 */
function parseJepsenLog(text, opts) {
  const source = (opts && opts.source) || '<input>';
  if (typeof text !== 'string') {
    throw new TypeError(source + ': expected log text as a string, got ' + typeof text);
  }
  if (text.length > MAX_BYTES) {
    throw new RangeError(
      source + ': log is ' + text.length + ' bytes, over the ' + MAX_BYTES + ' byte limit'
    );
  }
  if (text.trim() === '') {
    throw new Error(source + ': file is empty');
  }
  if (text.indexOf('\u0000') !== -1) {
    throw new Error(source + ': contains NUL bytes, this does not look like a Jepsen text log');
  }

  const lines = text.split(/\r?\n/);
  /** @type {import('../lin/history.js').Operation[]} */
  const ops = [];
  /** @type {Map<number, import('../lin/history.js').Operation>} */
  const pending = new Map();
  let pos = 0;
  let id = 0;
  let recognised = 0;

  /**
   * @param {number} proc
   * @param {object} input
   */
  const open = (proc, input) => {
    if (pending.has(proc)) {
      throw new Error(
        source +
          ': process ' +
          proc +
          ' invoked a new operation while one was still outstanding; ' +
          'this history is not well formed (a client must be sequential)'
      );
    }
    /** @type {import('../lin/history.js').Operation} */
    const op = { id: id++, clientId: proc, key: 'x', input, output: {}, call: pos++, ret: -1 };
    pending.set(proc, op);
    ops.push(op);
  };

  /**
   * @param {number} proc
   * @param {object} output
   */
  const close = (proc, output) => {
    const op = pending.get(proc);
    if (!op) return; // a response with no invocation; Porcupine ignores these too
    pending.delete(proc);
    op.output = output;
    op.ret = pos++;
  };

  for (const rawLine of lines) {
    const line = rawLine.trimEnd();
    if (line === '') continue;
    let m;
    if ((m = RE.invokeRead.exec(line))) {
      open(Number(m[1]), { op: 'read' });
      recognised++;
    } else if ((m = RE.invokeWrite.exec(line))) {
      open(Number(m[1]), { op: 'write', arg1: Number(m[2]) });
      recognised++;
    } else if ((m = RE.invokeCas.exec(line))) {
      open(Number(m[1]), { op: 'cas', arg1: Number(m[2]), arg2: Number(m[3]) });
      recognised++;
    } else if ((m = RE.returnRead.exec(line))) {
      const exists = m[2] !== 'nil';
      close(Number(m[1]), { exists, value: exists ? Number(m[2]) : 0 });
      recognised++;
    } else if ((m = RE.returnWrite.exec(line))) {
      close(Number(m[1]), {});
      recognised++;
    } else if ((m = RE.returnCas.exec(line))) {
      close(Number(m[1]), { ok: m[2] === 'ok' });
      recognised++;
    } else if ((m = RE.timeoutRead.exec(line))) {
      close(Number(m[1]), { unknown: true });
      recognised++;
    }
    // everything else, including `:info <op> :timed-out`, is skipped on purpose
  }

  if (recognised === 0) {
    throw new Error(
      source + ': no Jepsen operations found; expected lines like "INFO  jepsen.util - 0\t:invoke\t:read\tnil"'
    );
  }

  const stillOpen = Array.from(pending.values()).sort((a, b) => a.clientId - b.clientId);
  for (const op of stillOpen) {
    op.output = { unknown: true };
    op.ret = pos++;
  }

  return ops;
}

__exports.parseJepsenLog = parseJepsenLog;
};
__defs["web/app.js"] = function (__exports, __req) {
// The demo page's controller.
//
// This is the UI layer, and the only place in the project allowed to touch the
// clock or the DOM. Everything it calls -- the scheduler, the Raft nodes, the
// checker -- is the same code the CLI and the test suite run, so what the page
// shows is not a re-implementation that could drift.

const { runSimulation } = __req("src/raft/cluster.js");
const { check } = __req("src/lin/wgl.js");
const { kvRegisterModel, etcdRegisterModel } = __req("src/lin/models.js");
const { parseJepsenLog } = __req("src/io/jepsen.js");
const { parseBuildFlags, correctBuild, BUGS } = __req("src/bugs.js");

const DEFAULTS = {
  seed: 4711,
  faults: '150-700:L',
  build: 'deposed-leader-read',
  ops: 60,
};

const FAULT_PRESETS = [
  { value: '', label: 'None' },
  { value: '150-700:L', label: 'Partition the leader away (ticks 150-700)' },
  { value: '200-500:0.1,600-900:2.3', label: 'Two cuts: {0,1} then {2,3}' },
  {
    value: 'c120-200:L,c220-300:L,c320-400:L,c420-500:L,c520-600:L,c620-700:L',
    label: 'Crash the leader, six times over',
  },
];

const el = (id) => /** @type {HTMLElement} */ (document.getElementById(id));

/** @returns {{seed:number, faults:string, build:string, ops:number}} */
function stateFromUrl() {
  const p = new URLSearchParams(window.location.search);
  const seed = Number.parseInt(p.get('seed') || '', 10);
  const ops = Number.parseInt(p.get('ops') || '', 10);
  return {
    seed: Number.isInteger(seed) ? seed : DEFAULTS.seed,
    faults: p.get('faults') === null ? DEFAULTS.faults : /** @type {string} */ (p.get('faults')),
    build: p.get('build') === null ? DEFAULTS.build : /** @type {string} */ (p.get('build')),
    ops: Number.isInteger(ops) && ops > 0 && ops <= 200 ? ops : DEFAULTS.ops,
  };
}

/** @param {{seed:number, faults:string, build:string, ops:number}} s */
function urlFor(s) {
  const p = new URLSearchParams();
  p.set('seed', String(s.seed));
  p.set('faults', s.faults);
  p.set('build', s.build);
  p.set('ops', String(s.ops));
  return window.location.origin + window.location.pathname + '?' + p.toString();
}

// --------------------------------------------------------------------------

const PALETTE = {
  put: '#5b8def',
  get: '#38b48b',
  unknown: '#8a8f98',
  blocked: '#e5484d',
  prefix: '#f5a524',
};

/**
 * @param {any} sim
 * @param {any} res
 * @returns {string} SVG markup
 */
function diagram(sim, res) {
  const ops = sim.history;
  if (ops.length === 0) return '<p class="muted">no operations</p>';

  const clients = Array.from(new Set(ops.map((/** @type {any} */ o) => o.clientId))).sort(
    (/** @type {number} */ a, /** @type {number} */ b) => a - b
  );
  const rowOf = new Map(clients.map((c, i) => [c, i]));

  const minTick = Math.min(...ops.map((/** @type {any} */ o) => o.callTick));
  const maxTick = Math.max(...ops.map((/** @type {any} */ o) => Math.max(o.callTick, o.retTick)));
  const span = Math.max(1, maxTick - minTick);

  const padL = 66;
  const padR = 18;
  const padT = 40;
  const rowH = 28;
  const width = 1000;
  const plotW = width - padL - padR;
  const plotH = clients.length * rowH;
  const height = padT + plotH + 46;

  const x = (/** @type {number} */ t) => padL + ((t - minTick) / span) * plotW;

  const blocked = res.witness ? res.witness.blocked : null;
  const prefix = res.witness ? res.witness.prefix : [];
  // Only the LAST operation of the longest working ordering is marked. Outlining
  // all of them turns the picture into noise, and it is the last one that the
  // witness sentence actually names.
  const anchor = prefix.length > 0 ? prefix[prefix.length - 1] : null;

  const parts = [];
  parts.push(
    '<svg viewBox="0 0 ' + width + ' ' + height +
      '" role="img" aria-label="Space-time diagram of the client history" xmlns="http://www.w3.org/2000/svg">'
  );
  parts.push(
    '<defs><marker id="open" viewBox="0 0 6 6" refX="1" refY="3" markerWidth="5" markerHeight="5" orient="auto">' +
      '<path d="M0 0 L5 3 L0 6" fill="none" stroke="#8a8f98" stroke-width="1.2"/></marker></defs>'
  );

  for (const f of sim.faults) {
    const a = x(Math.max(minTick, f.start));
    const b = x(Math.min(maxTick, f.end));
    if (b <= a) continue;
    parts.push(
      '<rect class="fault ' + f.kind + '" x="' + a.toFixed(1) + '" y="' + (padT - 14) +
        '" width="' + (b - a).toFixed(1) + '" height="' + (plotH + 14) + '"/>'
    );
    parts.push(
      '<text class="faultlabel" x="' + (a + 6).toFixed(1) + '" y="' + (padT - 20) + '">' +
        (f.kind === 'crash' ? 'crash' : 'partition') + (f.group.length ? ' node ' + f.group.join(', ') : '') +
        '</text>'
    );
  }

  parts.push(
    '<line class="axis" x1="' + padL + '" y1="' + (padT - 14) +
      '" x2="' + padL + '" y2="' + (padT + plotH) + '"/>'
  );
  parts.push('<text class="tick" x="' + padL + '" y="' + (height - 14) + '">tick ' + minTick + '</text>');
  parts.push(
    '<text class="tick" text-anchor="end" x="' + (width - padR) + '" y="' + (height - 14) + '">' +
      maxTick + '</text>'
  );

  for (const c of clients) {
    const y = padT + /** @type {number} */ (rowOf.get(c)) * rowH + rowH / 2;
    parts.push(
      '<text class="lane" x="' + (padL - 10) + '" y="' + (y + 4) +
        '" text-anchor="end">client ' + c + '</text>'
    );
    parts.push('<line class="lane-rule" x1="' + padL + '" y1="' + y + '" x2="' + (width - padR) + '" y2="' + y + '"/>');
  }

  // A guide line through the offending operation, so the eye finds it before
  // it has read anything.
  if (blocked) {
    const gx = x(blocked.callTick);
    parts.push(
      '<line class="guide" x1="' + gx.toFixed(1) + '" y1="' + (padT - 14) + '" x2="' + gx.toFixed(1) +
        '" y2="' + (padT + plotH) + '"/>'
    );
  }

  for (const o of ops) {
    const y = padT + /** @type {number} */ (rowOf.get(o.clientId)) * rowH + rowH / 2;
    const a = x(o.callTick);
    const b = Math.max(a + 3, x(o.retTick));
    const label = kvRegisterModel.describe(o);
    const title = '<title>' + escapeXml(label) + ' (ticks ' + o.callTick + '-' + o.retTick + ')</title>';

    if (o.output && o.output.unknown) {
      // Never answered. Drawn open-ended rather than as a solid bar, because a
      // solid bar claims an end the client never saw -- and these span most of
      // the run, so drawing them heavy would bury everything else.
      parts.push(
        '<g class="op op-unknown">' + title +
          '<line x1="' + a.toFixed(1) + '" y1="' + y + '" x2="' + (b - 6).toFixed(1) + '" y2="' + y +
          '" marker-end="url(#open)"/>' +
          '<circle cx="' + a.toFixed(1) + '" cy="' + y + '" r="3"/></g>'
      );
      continue;
    }

    const isBlocked = blocked && o.id === blocked.id;
    const isAnchor = anchor && o.id === anchor.id;
    const fill = isBlocked ? PALETTE.blocked : o.input.op === 'put' ? PALETTE.put : PALETTE.get;
    const cls = 'op' + (isBlocked ? ' op-blocked' : isAnchor ? ' op-anchor' : '');
    // The offending operation is drawn taller and carries a caret, because it is
    // the one thing on this page a visitor has to be able to find in a second.
    const h = isBlocked ? 18 : 12;
    const w = Math.max(b - a, isBlocked ? 7 : 3);
    parts.push(
      '<g class="' + cls + '">' + title +
        '<rect x="' + a.toFixed(1) + '" y="' + (y - h / 2) + '" width="' + w.toFixed(1) +
        '" height="' + h + '" rx="3" fill="' + fill + '"/>' +
        (isBlocked
          ? '<path class="caret" d="M' + (a + w / 2 - 5).toFixed(1) + ' ' + (y - h / 2 - 5) +
            ' L' + (a + w / 2 + 5).toFixed(1) + ' ' + (y - h / 2 - 5) +
            ' L' + (a + w / 2).toFixed(1) + ' ' + (y - h / 2 - 1) + ' Z"/>'
          : '') +
        '</g>'
    );
  }

  // Callouts last, so nothing is drawn over them, and nudged apart if the two
  // operations happen to sit on neighbouring rows at the same instant.
  /** @type {Array<{x:number,y:number,w:number}>} */
  const placed = [];
  const geom = { padT, rowH, width, padR, rowOf };
  if (anchor) {
    const t = 'last step that works: ' + kvRegisterModel.describe(anchor);
    parts.push(callout(x, anchor, geom, placed, 'anchor', t));
  }
  if (blocked) {
    const t = kvRegisterModel.describe(blocked) + '  <- no ordering explains this';
    parts.push(callout(x, blocked, geom, placed, 'blocked', t));
  }

  parts.push('</svg>');
  return parts.join('');
}

/**
 * A label with its own backing plate, placed on whichever side of the operation
 * has room.
 * @returns {string}
 */
function callout(x, op, geom, placed, kind, text) {
  const y = geom.padT + geom.rowOf.get(op.clientId) * geom.rowH + geom.rowH / 2;
  const right = x(op.retTick) + 12;
  const charW = 6.6;
  const w = text.length * charW + 14;
  const fitsRight = right + w < geom.width - geom.padR;
  const bx = fitsRight ? right : Math.max(2, x(op.callTick) - 12 - w);
  let ty = y - 13;
  // Nudge down until this box clears every box already drawn.
  for (let guard = 0; guard < 8; guard++) {
    const clash = placed.some(
      (b) => Math.abs(b.y - ty) < 17 && bx < b.x + b.w + 6 && b.x < bx + w + 6
    );
    if (!clash) break;
    ty += 19;
  }
  placed.push({ x: bx, y: ty, w });
  return (
    '<g class="callout callout-' + kind + '">' +
    '<rect x="' + bx.toFixed(1) + '" y="' + (ty - 11) + '" width="' + w.toFixed(1) + '" height="16" rx="3"/>' +
    '<text x="' + (bx + 7).toFixed(1) + '" y="' + ty + '">' + escapeXml(text) + '</text>' +
    '</g>'
  );
}

/** @param {string} s */
function escapeXml(s) {
  return String(s).replace(/[<>&"]/g, (c) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' }[c] || c));
}

// --------------------------------------------------------------------------

/** @param {{seed:number, faults:string, build:string, ops:number}} s */
function runAndRender(s) {
  let flags;
  try {
    flags = s.build === '' || s.build === 'correct' ? correctBuild() : parseBuildFlags(s.build);
  } catch (err) {
    showError(/** @type {Error} */ (err).message);
    return;
  }

  let sim;
  try {
    sim = runSimulation({
      seed: s.seed,
      faults: s.faults,
      operations: s.ops,
      clients: 4,
      nodes: 5,
      keys: 1,
      maxEntriesPerAppend: s.build === 'stale-term-commit' ? 1 : 8,
      flags,
    });
  } catch (err) {
    showError(/** @type {Error} */ (err).message);
    return;
  }

  const res = check(kvRegisterModel, sim.history, { budget: 2000000 });

  const verdict = el('verdict');
  verdict.className = 'verdict verdict-' + res.verdict;
  el('verdict-word').textContent =
    res.verdict === 'not-linearizable'
      ? 'not linearizable'
      : res.verdict === 'linearizable'
        ? 'linearizable'
        : 'unknown';
  el('verdict-detail').textContent =
    'seed ' + s.seed + ' · ' + res.steps.toLocaleString() + ' steps · ' + res.operations + ' operations';

  const witness = el('witness');
  if (res.verdict === 'not-linearizable' && res.witness) {
    witness.hidden = false;
    witness.textContent = 'witness: ' + res.witness.text;
  } else if (res.verdict === 'unknown') {
    witness.hidden = false;
    witness.textContent =
      'the search exhausted its ' + res.budget.toLocaleString() +
      '-step budget. That is not a pass: it means this history is too hard to decide in the time you would wait.';
  } else {
    witness.hidden = false;
    witness.textContent =
      'every client response can be explained by some single order of the operations. Switch the build to a ' +
      'planted bug to see the other answer.';
  }

  el('diagram').innerHTML = diagram(sim, res);

  el('stats').innerHTML = [
    stat('nodes', String(sim.config.nodes)),
    stat('leader changes', String(sim.stats.leaderChanges)),
    stat('messages', sim.stats.messagesSent.toLocaleString()),
    stat('dropped', sim.stats.messagesDropped.toLocaleString()),
    stat('never answered', String(sim.stats.unfinished)),
    stat('simulated ticks', sim.stats.ticks.toLocaleString()),
  ].join('');

  el('permalink').setAttribute('href', urlFor(s));
  const url = new URL(window.location.href);
  url.search = new URL(urlFor(s)).search;
  window.history.replaceState(null, '', url.toString());
  el('error').hidden = true;
}

/** @param {string} k @param {string} v */
function stat(k, v) {
  return '<div class="stat"><dt>' + k + '</dt><dd>' + v + '</dd></div>';
}

/** @param {string} message */
function showError(message) {
  const e = el('error');
  e.hidden = false;
  e.textContent = message;
}

// --------------------------------------------------------------------------
// The real-Jepsen panel. Two histories vendored from Porcupine's test data,
// with the verdicts Porcupine publishes for them, checked live in the page.

function renderSamples() {
  /** @type {any} */
  const samples = /** @type {any} */ (window).KEDGE_SAMPLES || {};
  const rows = [];
  for (const file of Object.keys(samples)) {
    const s = samples[file];
    const t0 = performance.now();
    const history = parseJepsenLog(s.text, { source: file });
    const res = check(etcdRegisterModel, history, { budget: 4000000 });
    const ms = Math.round(performance.now() - t0);
    const agrees = res.verdict === s.expected;
    rows.push(
      '<tr><td><code>' + file + '</code></td>' +
        '<td>' + history.length + '</td>' +
        '<td>' + s.expected + '</td>' +
        '<td>' + res.verdict + '</td>' +
        '<td>' + res.steps.toLocaleString() + '</td>' +
        '<td>' + ms + ' ms</td>' +
        '<td class="' + (agrees ? 'agree' : 'disagree') + '">' + (agrees ? 'agrees' : 'DISAGREES') + '</td></tr>'
    );
  }
  el('samples-body').innerHTML = rows.join('');
}

// --------------------------------------------------------------------------

function init() {
  const buildSelect = /** @type {HTMLSelectElement} */ (el('build'));
  buildSelect.innerHTML =
    '<option value="correct">correct build</option>' +
    BUGS.filter((b) => b.target === 'raft')
      .map((b) => '<option value="' + b.id + '">' + b.id + '</option>')
      .join('');

  const faultSelect = /** @type {HTMLSelectElement} */ (el('faults'));
  faultSelect.innerHTML = FAULT_PRESETS.map(
    (f) => '<option value="' + escapeXml(f.value) + '">' + escapeXml(f.label) + '</option>'
  ).join('');

  const s = stateFromUrl();
  /** @type {HTMLInputElement} */ (el('seed')).value = String(s.seed);
  buildSelect.value = s.build === '' ? 'correct' : s.build;
  if (!FAULT_PRESETS.some((f) => f.value === s.faults)) {
    faultSelect.innerHTML +=
      '<option value="' + escapeXml(s.faults) + '">' + escapeXml(s.faults) + ' (from link)</option>';
  }
  faultSelect.value = s.faults;

  const current = () => ({
    seed: Number.parseInt(/** @type {HTMLInputElement} */ (el('seed')).value, 10) || 0,
    faults: faultSelect.value,
    build: buildSelect.value,
    ops: s.ops,
  });

  const rerun = () => runAndRender(current());
  el('seed').addEventListener('change', rerun);
  faultSelect.addEventListener('change', rerun);
  buildSelect.addEventListener('change', rerun);
  el('reroll').addEventListener('click', () => {
    // The one place a random number is welcome: choosing which deterministic
    // execution to look at next.
    const next = Math.floor(Math.random() * 100000);
    /** @type {HTMLInputElement} */ (el('seed')).value = String(next);
    rerun();
  });
  el('hunt').addEventListener('click', () => {
    const base = current();
    let flags;
    try {
      flags = base.build === 'correct' ? correctBuild() : parseBuildFlags(base.build);
    } catch {
      return;
    }
    for (let i = 0; i < 300; i++) {
      const seed = base.seed + 1 + i;
      const sim = runSimulation({
        seed,
        faults: base.faults,
        operations: base.ops,
        clients: 4,
        nodes: 5,
        keys: 1,
        maxEntriesPerAppend: base.build === 'stale-term-commit' ? 1 : 8,
        flags,
      });
      if (check(kvRegisterModel, sim.history, { budget: 2000000 }).verdict === 'not-linearizable') {
        /** @type {HTMLInputElement} */ (el('seed')).value = String(seed);
        rerun();
        return;
      }
    }
    showError(
      'searched 300 seeds from ' + (base.seed + 1) + ' and found no violation with this build and fault script. ' +
        'On the correct build that is the expected answer.'
    );
  });

  runAndRender(s);
  try {
    renderSamples();
  } catch (err) {
    el('samples-body').innerHTML =
      '<tr><td colspan="7">could not check the vendored histories: ' +
      escapeXml(/** @type {Error} */ (err).message) + '</td></tr>';
  }
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}

};
__req("web/app.js");
